import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {StoreCannotList} from '../types/sessionStore.js';

describe('history opt-in', () => {
  const clients: WebSocket[] = [];
  const servers: any[] = [];

  afterEach(async () => {
    await cleanup(clients, servers);
  });

  async function getListResponse(config: any, outbound: any = {type: 'list_sessions'}): Promise<any> {
    const {url, hal} = await startEngineWith(config);
    servers.push(hal);

    const client = connectClient(url);
    clients.push(client);

    return new Promise<any>(resolve => {
      client.on('message', raw => {
        const f = JSON.parse(String(raw));
        if (f.type === 'connected') {
          client.send(JSON.stringify(outbound));
        } else if (f.type !== 'pong') {
          resolve(f);
        }
      });
    });
  }

  it('answers UNSUPPORTED when history is not enabled ([validated by](../../specs/hal-engine-websocket-protocol/spec.md#L126))', async () => {
    const store = new InMemorySessionStore();
    const frame = await getListResponse({
      sessionStore: delegatingTo(store),
    });

    expect(frame).toEqual({
      type: 'error',
      code: 'UNSUPPORTED',
      message: 'History is not supported',
    });
  });

  it('answers UNSUPPORTED when history is enabled but store does not support listing ([validated by](../../specs/hal-engine-websocket-protocol/spec.md#L126))', async () => {
    const store = new InMemorySessionStore();
    const frame = await getListResponse({
      sessionStore: delegatingTo(store), // delegatingTo strips listFor
      history: {enabled: true},
    });

    expect(frame).toEqual({
      type: 'error',
      code: 'UNSUPPORTED',
      message: 'History is not supported',
    });
  });

  it('answers UNSUPPORTED when store throws StoreCannotList ([validated by](../../specs/hal-engine-websocket-protocol/spec.md#L126))', async () => {
    const inner = new InMemorySessionStore();
    const store = {
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new StoreCannotList('mongo collection has no find')),
    };
    const frame = await getListResponse({
      sessionStore: store,
      history: {enabled: true},
    });

    expect(frame).toEqual({
      type: 'error',
      code: 'UNSUPPORTED',
      message: 'History is not supported by the store',
    });
  });

  it('answers session_list when history is enabled and store supports listing ([validated by](../../specs/hal-engine-websocket-protocol/spec.md#L182))', async () => {
    const store = new InMemorySessionStore();
    const frame = await getListResponse({
      sessionStore: store,
      history: {enabled: true},
